create table public.rahyar_stations (
 id text primary key, name text not null, latitude double precision not null,
 longitude double precision not null, source text not null
);
alter table public.rahyar_stations enable row level security;
revoke all on public.rahyar_stations from anon,authenticated;
grant select on public.rahyar_stations to authenticated;
create policy station_read on public.rahyar_stations for select to authenticated using(true);
create function rahyar_private.check_station_observation() returns trigger
language plpgsql security invoker set search_path='' as $$
declare station public.rahyar_stations;
begin
 if new.category='weigh' then
  select * into station from public.rahyar_stations where id=new.station_key;
  if not found then raise exception 'Station is not in the verified government inventory' using errcode='22023'; end if;
  if sqrt(power((new.latitude-station.latitude)*111320,2)+power((new.longitude-station.longitude)*111320*cos(radians(station.latitude)),2))>1500 then
   raise exception 'Observe the station from within 1.5 km; never report a distant sign' using errcode='22023';
  end if;
  if new.heading is null then raise exception 'Travel direction is required for station observations' using errcode='22023'; end if;
 end if;
 return new;
end $$;
revoke all on function rahyar_private.check_station_observation() from public,anon,authenticated;
create trigger rahyar_station_check before insert on public.rahyar_road_reports for each row execute function rahyar_private.check_station_observation();
